"use strict";(globalThis.webpackChunkadri_docs=globalThis.webpackChunkadri_docs||[]).push([[4419],{28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var i=n(96540);const a={},o=i.createContext(a);function s(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:t},e.children)}},71679:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>i,toc:()=>h});const i=JSON.parse('{"id":"case-studies/v2","title":"What Does the SAP Developer Own When an Agent Writes the Code?","description":"A workflow change shows how an SAP developer, an agent, and BASIS divide implementation work, decisions, and responsibility.","source":"@site/docs/case-studies/v2.md","sourceDirName":"case-studies","slug":"/case-studies/sap-developer-responsibilities-with-agents","permalink":"/case-studies/sap-developer-responsibilities-with-agents","draft":false,"unlisted":false,"editUrl":"https://github.com/GetAdriAI/adri-docs/tree/main/docs/case-studies/v2.md","tags":[],"version":"current","lastUpdatedBy":"darshitac11","lastUpdatedAt":1791281172000,"sidebarPosition":3,"frontMatter":{"title":"What Does the SAP Developer Own When an Agent Writes the Code?","sidebar_position":3,"sidebar_label":"SAP Developer Responsibilities (v2)","description":"A workflow change shows how an SAP developer, an agent, and BASIS divide implementation work, decisions, and responsibility.","slug":"/case-studies/sap-developer-responsibilities-with-agents"},"sidebar":"tutorialSidebar","previous":{"title":"SAP Developer Responsibilities with Agents","permalink":"/case-studies/modernizing-a-14-year-old-sap-workflow-rewritten"},"next":{"title":"SAP Developer Responsibilities (v3)","permalink":"/case-studies/v3"}}');var a=n(74848),o=n(28453);const s={title:"What Does the SAP Developer Own When an Agent Writes the Code?",sidebar_position:3,sidebar_label:"SAP Developer Responsibilities (v2)",description:"A workflow change shows how an SAP developer, an agent, and BASIS divide implementation work, decisions, and responsibility.",slug:"/case-studies/sap-developer-responsibilities-with-agents"},r=void 0,d={},h=[{value:"How was the work divided?",id:"how-was-the-work-divided",level:2},{value:"We need a way back if this goes wrong.",id:"we-need-a-way-back-if-this-goes-wrong",level:2},{value:"Can we actually make that authorization change here?",id:"can-we-actually-make-that-authorization-change-here",level:2},{value:"Where will the test emails actually go?",id:"where-will-the-test-emails-actually-go",level:2},{value:"What does this mean for the developer or architect?",id:"what-does-this-mean-for-the-developer-or-architect",level:2}];function l(e){const t={h2:"h2",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"If an agent can investigate your custom code, write a solution, and run the tests, what exactly is the SAP developer supposed to do?"}),"\n",(0,a.jsx)(t.p,{children:"One of our clients had a useful example. They wanted to improve a purchase requisition approval email: include the PR details and add a link that opened the specific requisition in ME54N through SAP Web GUI."}),"\n",(0,a.jsx)(t.p,{children:"Reasonable enough. Except the workflow was 14 years old, its original developer had left, and nobody on the current team knew it particularly well."}),"\n",(0,a.jsx)(t.p,{children:"The client used Adri. I am affiliated with Adri, so this is the example I know firsthand. The part I want to discuss is how the agent, developer, and BASIS team divided the work."}),"\n",(0,a.jsx)(t.h2,{id:"how-was-the-work-divided",children:"How was the work divided?"}),"\n",(0,a.jsx)(t.p,{children:"Follow the handoffs at the authorization blocker and the email risk. These are the points where the developer had to determine what could happen next."}),"\n",(0,a.jsx)(t.mermaid,{value:"sequenceDiagram\n    participant D as SAP Developer\n    participant A as Agent\n    participant B as BASIS\n\n    Note over D,B: 1. Set the constraint\n    D->>A: Make the change reversible\n\n    Note over D,B: 2\u20133. Investigate and implement\n    A->>A: Trace code, configuration, and dependencies\n    A->>A: Develop, iterate, and unit-test\n\n    Note over D,B: 4. Resolve authorization blocker\n    A->>D: Report blocker and propose required change\n    D->>B: Check feasibility and coordinate request\n    B--\x3e>D: Required update completed\n    D->>A: Confirm update and guide continuation\n    A->>A: Complete remaining implementation\n\n    Note over D,B: 5. Make testing safe\n    A->>D: Flag outbound-email risk and pause testing\n    D->>B: Coordinate email containment\n    B--\x3e>D: Safety measure in place\n    D->>A: Confirm testing can proceed\n\n    Note over D,B: 6\u20138. Test, hand over, and retain learning\n    A->>A: Run end-to-end tests, then deliver transports<br/>and specification, then record findings"}),"\n",(0,a.jsx)(t.p,{children:"The agent investigated approver identification, release strategy, and email delivery. It developed the email class and the workflow nodes and containers needed to call it. There were failed attempts and rework before it found an approach that fit the system."}),"\n",(0,a.jsx)(t.p,{children:"After testing, it delivered the transports and technical specification and recorded the email-delivery pattern in the knowledge graph for future work. This account covers implementation and sandbox testing; it does not establish who approved or carried out the production deployment."}),"\n",(0,a.jsx)(t.p,{children:"Three decisions in that sequence are worth looking at more closely."}),"\n",(0,a.jsx)(t.h2,{id:"we-need-a-way-back-if-this-goes-wrong",children:"We need a way back if this goes wrong."}),"\n",(0,a.jsx)(t.p,{children:"The developer made reversibility a success criterion before delegating the implementation."}),"\n",(0,a.jsx)(t.p,{children:"The workflow already worked. The team did not know it deeply. If the change behaved unexpectedly, they needed a clear path back to the working version."}),"\n",(0,a.jsx)(t.p,{children:"An agent can identify several technical concerns. Someone still has to rank them in the context of the business and the team's ability to recover. Here, the developer decided that being able to undo the change mattered enough to shape the solution."}),"\n",(0,a.jsx)(t.p,{children:"That is a requirement you can easily miss if the task you hand over is simply \u201cadd PR details and a button to this email.\u201d"}),"\n",(0,a.jsx)(t.p,{children:"For me, this is one responsibility that becomes more explicit when working with agents: describe the conditions that make a solution acceptable, as well as the functionality you want it to produce."}),"\n",(0,a.jsx)(t.h2,{id:"can-we-actually-make-that-authorization-change-here",children:"Can we actually make that authorization change here?"}),"\n",(0,a.jsx)(t.p,{children:"During implementation, the agent found that it lacked the authorization to modify the workflow. It diagnosed the issue, prepared a detailed request for BASIS, and paused."}),"\n",(0,a.jsx)(t.p,{children:"The developer took that request to the relevant stakeholders and checked whether it was viable in the client's environment. A proposed change can be technically sensible and still run into security policy or operational constraints."}),"\n",(0,a.jsx)(t.p,{children:"This is where knowing the landscape and the people responsible for it matters. The developer had to understand the request well enough to discuss it, bring constraints back to the agent, and guide the next move."}),"\n",(0,a.jsx)(t.p,{children:"BASIS completed the required update. The agent then resumed and finished the implementation."}),"\n",(0,a.jsx)(t.p,{children:"The developer was doing more than forwarding a message. They were connecting a proposed technical solution with the organization that had to permit and support it."}),"\n",(0,a.jsx)(t.h2,{id:"where-will-the-test-emails-actually-go",children:"Where will the test emails actually go?"}),"\n",(0,a.jsx)(t.p,{children:"Before end-to-end testing, the agent identified that the sandbox could still deliver workflow emails to real users."}),"\n",(0,a.jsx)(t.p,{children:"Calling it a sandbox does not help much when your test lands in an actual approver's inbox."}),"\n",(0,a.jsx)(t.p,{children:"The agent stopped and requested a safety measure for outbound email. The developer coordinated with BASIS to establish what the environment could support. BASIS put the measure in place, and testing resumed after confirmation."}),"\n",(0,a.jsx)(t.p,{children:"The agent spotted the risk in this case. The developer still had to coordinate the response and determine when it was safe to continue."}),"\n",(0,a.jsx)(t.p,{children:"There are several separate responsibilities here: identify the risk, propose a response, change the environment, and confirm that the next action can proceed. The diagram makes those handoffs visible. \u201cThe agent tested the workflow\u201d leaves quite a bit out."}),"\n",(0,a.jsx)(t.h2,{id:"what-does-this-mean-for-the-developer-or-architect",children:"What does this mean for the developer or architect?"}),"\n",(0,a.jsx)(t.p,{children:"These responsibilities will sound familiar to experienced SAP developers and architects. The shift is in how much execution they can delegate, and how deliberately they need to define the conditions around that work."}),"\n",(0,a.jsx)(t.p,{children:"In this case, the agent took on investigation, implementation, and test execution. The developer set a priority the solution had to respect, checked proposed changes against organizational constraints, and coordinated the decisions that let work resume. BASIS remained responsible for the environment changes described here."}),"\n",(0,a.jsx)(t.p,{children:"My takeaway for an agent-assisted SDLC is to agree on three things before work starts:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"What can the agent do within the agreed scope?"})," Define the task, constraints, and conditions that require it to pause."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"What evidence must come back?"})," Decide how the implementation, test results, and recovery approach will be reviewed."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Who can authorize the next step?"})," Name the people responsible for environment changes, acceptance, and release."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Those are recommendations drawn from the story. The account does not document every review and approval, and preparing a transport alone does not establish who owns its release."}),"\n",(0,a.jsx)(t.p,{children:"The developer had fewer implementation steps to execute personally, but still needed enough technical understanding to question the approach and make consequential decisions. For an architect, the same questions extend across the systems and teams affected by a change."}),"\n",(0,a.jsx)(t.p,{children:"That is the question I would bring to the next project: when we delegate the work, have we also made clear who owns the decisions around it?"})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}}}]);